"""Dependency-free Playlist Analysis Deck page."""

PLAYLIST_HTML = r'''<!doctype html>
<html><head><meta charset="utf-8"><title>CrateIQ Playlists</title><style>
:root{--bg:#0b1020;--panel:#151d32;--line:#28334f;--muted:#9aa6bf;--text:#edf2ff;--cyan:#54d5ff;--amber:#f6c967;--coral:#ff7285;--green:#71d69b}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:14px system-ui}.shell{width:min(1600px,96vw);margin:auto;padding:28px 0 60px}.top,.controls,.track{display:flex;gap:14px;align-items:center}.top{justify-content:space-between;border-bottom:1px solid var(--line);padding-bottom:20px}.eyebrow{color:var(--cyan);font-size:11px;letter-spacing:.14em;text-transform:uppercase}h1{margin:4px 0;font-size:32px}.nav,a{color:var(--cyan)}button,input,select{background:#1b2740;color:var(--text);border:1px solid #3c4d72;border-radius:8px;padding:10px 12px}button{cursor:pointer;font-weight:700}.primary{background:var(--cyan);color:#06101b}.panel{background:var(--panel);border:1px solid var(--line);border-radius:14px;padding:18px;margin-top:20px}.controls{flex-wrap:wrap}.controls select{min-width:300px;flex:1}.flow{height:260px;width:100%;background:#10182a;border-radius:10px;margin-top:16px}.legend{display:flex;gap:14px;flex-wrap:wrap;color:var(--muted);font-size:12px}.legend i{display:inline-block;width:10px;height:3px;vertical-align:middle;margin-right:4px}.cards{display:grid;gap:9px;margin-top:14px}.track{background:#10182a;border-radius:10px;padding:11px;cursor:pointer}.track:hover{outline:1px solid var(--cyan)}.position{color:var(--muted);width:26px}.track-main{flex:1;min-width:0}.track-main small{color:var(--muted)}.badge{font-size:11px;padding:4px 7px;border-radius:999px;background:#28334f}.bad{background:#643143;color:#ffd8df}.warn{background:#5c512b;color:#fff0b5}.ok{background:#1f5742;color:#c8f6da}.actions{display:flex;gap:6px}.actions button{padding:6px 9px;font-size:12px}.editor{display:grid;grid-template-columns:1fr 1fr;gap:14px}.picker-results{max-height:210px;overflow:auto}.pick{display:flex;gap:8px;padding:7px;border-bottom:1px solid #28334f}.empty{color:var(--muted);padding:18px;text-align:center}@media(max-width:800px){.top,.editor{display:block}.nav{margin-top:12px}.controls select{width:100%;margin:8px 0}.track{align-items:flex-start}.badges{display:grid;gap:4px}}
</style></head><body><main class="shell"><header class="top"><div><div class="eyebrow">Playlist analysis deck</div><h1>CrateIQ Playlists</h1><div class="muted">Plan the musical flow before the next transition.</div></div><nav class="nav"><a href="/">Track analysis</a></nav></header><section class="panel"><div class="controls"><select id="playlist"></select><button id="new" class="primary">New playlist</button><button id="rename">Rename</button><button id="restore">Restore source order</button><button id="delete">Delete local copy</button></div><div id="overview"></div><svg id="flow" class="flow" viewBox="0 0 1000 260" preserveAspectRatio="none"></svg><div class="legend"><span><i style="background:#54d5ff"></i>Energy</span><span><i style="background:#ff7285"></i>Bass</span><span><i style="background:#f6c967"></i>Rhythm</span><span><i style="background:#ba8df5"></i>Brightness</span><span><i style="background:#71d69b"></i>Tempo (normalized)</span><span>Raw BPM is shown on each track.</span></div></section><section class="panel"><div class="eyebrow">Ordered tracks</div><div id="tracks" class="cards"></div></section><section class="panel"><div class="eyebrow">Add analyzed tracks</div><div class="editor"><div><input id="search" type="search" placeholder="Search title or artist"><div id="results" class="picker-results"></div></div><div><p class="muted">Selected tracks are appended to the editable local playlist.</p><div id="selected" class="picker-results"></div><button id="create" class="primary">Create playlist from selection</button></div></div></section></main><script>
let catalog=[],playlists=[],current='',detail=null,chosen=[];const $=id=>document.getElementById(id);const esc=v=>String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));const fmt=v=>typeof v==='number'&&Number.isFinite(v)?(Math.abs(v)>=100?Math.round(v):v.toFixed(2)):'—';
async function request(url,options){let response=await fetch(url,options);return response.json()}async function boot(){[catalog,playlists]=await Promise.all([request('/api/tracks'),request('/api/playlists')]);renderPicker();current=playlists[0]?.id||'';if(current)load()}
function renderPicker(){let selected=current;$('playlist').innerHTML=playlists.map(p=>`<option value="${p.id}">${esc(p.name)} · ${p.trackCount} tracks${p.source==='rekordbox'?' · Rekordbox':''}</option>`).join('');$('playlist').value=selected}
async function refresh(selectId){playlists=await request('/api/playlists');current=selectId||current||playlists[0]?.id||'';renderPicker();if(current)load()}
async function load(){if(!current)return;detail=await request(`/api/playlist?playlist_id=${encodeURIComponent(current)}`);renderDetail()}
function line(points,color){if(!points.length)return '';return `<polyline fill="none" stroke="${color}" stroke-width="3" points="${points.map((v,i)=>`${50+i*900/Math.max(points.length-1,1)},${235-v*190}`).join(' ')}"/>`}
function renderDetail(){let valid=detail.tracks.filter(t=>t.available).length;$('overview').innerHTML=`<h2>${esc(detail.name)}</h2><div class="muted">${detail.tracks.length} tracks · ${valid} analyzed · ${detail.source==='rekordbox'?'Imported from Rekordbox XML':'Editable CrateIQ playlist'}</div>`;$('flow').innerHTML=`<line x1="50" y1="235" x2="950" y2="235" stroke="#526079"/>${line(detail.trends.energy,'#54d5ff')}${line(detail.trends.bass,'#ff7285')}${line(detail.trends.rhythm,'#f6c967')}${line(detail.trends.brightness,'#ba8df5')}${line(detail.trends.tempo,'#71d69b')}`;$('tracks').innerHTML=detail.tracks.length?detail.tracks.map((t,i)=>`<article class="track" data-id="${t.id}"><span class="position">${i+1}</span><div class="track-main"><b>${esc(t.title)}</b> <small>· ${esc(t.artist||'Unknown artist')} · ${fmt(t.bpm)} BPM · ${esc(t.camelot||t.key||'—')}</small><br><small>${t.available?'Energy '+fmt(t.features.energy)+' · Bass '+fmt(t.features.bass)+' · Rhythm '+fmt(t.features.rhythm)+' · Brightness '+fmt(t.features.brightness):'Analysis unavailable'}</small>${t.transition.reasons.length?`<br><small>${esc(t.transition.reasons.join(' · '))}</small>`:''}${t.outlier.reasons.length?`<br><small>${esc(t.outlier.reasons.join(' · '))}</small>`:''}</div><div class="badges">${badge(t.transition)}${badge(t.outlier)}</div><div class="actions"><button data-action="up" ${i?'':'disabled'}>↑</button><button data-action="down" ${i<detail.tracks.length-1?'':'disabled'}>↓</button><button data-action="remove">Remove</button></div></article>`).join(''):'<div class="empty">No tracks yet. Search the analyzed library below to create a playlist.</div>';document.querySelectorAll('.track').forEach(node=>node.addEventListener('click',event=>{let action=event.target.dataset.action;if(action){event.stopPropagation();edit(action,Number([...document.querySelectorAll('.track')].indexOf(node)));return}window.location=`/?track_id=${encodeURIComponent(node.dataset.id)}`}))}
function badge(item){return item.score?`<span class="badge ${item.severity==='high'?'bad':'warn'}">${esc(item.label)}</span>`:'<span class="badge ok">${esc(item.label)}</span>'}
async function edit(action,index){let ids=detail.tracks.map(t=>t.id);if(action==='remove')ids.splice(index,1);if(action==='up')([ids[index-1],ids[index]]=[ids[index],ids[index-1]]);if(action==='down')([ids[index+1],ids[index]]=[ids[index],ids[index+1]]);let value=await request('/api/playlists',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'update',playlist_id:current,track_ids:ids})});await refresh(value.id)}
$('playlist').addEventListener('change',e=>{current=e.target.value;load()});$('new').addEventListener('click',async()=>{let name=prompt('Playlist name');if(!name)return;let value=await request('/api/playlists',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'create',name,track_ids:[]})});await refresh(value.id)});$('rename').addEventListener('click',async()=>{if(!detail)return;let name=prompt('Playlist name',detail.name);if(!name)return;let value=await request('/api/playlists',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'update',playlist_id:current,name})});await refresh(value.id)});$('restore').addEventListener('click',async()=>{let value=await request('/api/playlists',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'restore',playlist_id:current})});if(value.id)await refresh(value.id)});$('delete').addEventListener('click',async()=>{if(!confirm('Delete this local playlist?'))return;await request('/api/playlists',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'delete',playlist_id:current})});current='';await refresh()});
function renderSearch(){let q=$('search').value.toLowerCase(),items=catalog.filter(t=>`${t.title} ${t.artist}`.toLowerCase().includes(q)).slice(0,25);$('results').innerHTML=items.map(t=>`<label class="pick"><input type="checkbox" data-id="${t.id}" ${chosen.includes(t.id)?'checked':''}><span>${esc(t.title)}<br><small>${esc(t.artist)}</small></span></label>`).join('');$('results').querySelectorAll('input').forEach(box=>box.addEventListener('change',()=>{chosen=box.checked?[...chosen,box.dataset.id]:chosen.filter(id=>id!==box.dataset.id);renderChosen();renderSearch()}))}function renderChosen(){$('selected').innerHTML=chosen.map((id,i)=>{let t=catalog.find(x=>x.id===id);return `<div class="pick">${i+1}. ${esc(t?.title||id)}</div>`}).join('')}$('search').addEventListener('input',renderSearch);$('create').addEventListener('click',async()=>{if(!chosen.length)return;let name=prompt('Playlist name');if(!name)return;let value=await request('/api/playlists',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'create',name,track_ids:chosen})});chosen=[];renderChosen();await refresh(value.id)});boot();
</script></body></html>'''
